async match(entityCode: string | null | undefined) {
  if (!entityCode) {
    return this.returnFallback();
  }

  try {
    return this.validateEntityCode(entityCode);
  } catch (error) {
    this.logger.debug("Failed to verify entity code", { error });

    return this.returnFallback();
  }
}

