async updateProduct(product: ProductWebhookPayloadFragment) {
  logger.debug(`updateProduct called`);

  if (!product.variants) {
    logger.debug("Product has no variants - abort");

    return;
  }

  const availability = await this.#getVariantsAvailability(product.variants);

  await Promise.all(
    product.variants.map((variant) => this.#saveProductVariant(variant, availability)),
  );
}

